from dataclasses import dataclass
from typing import List, Optional, Set, Tuple

from olmo_core.config import Config


def test_simple_config_as_dict():
    @dataclass
    class MockConfig(Config):
        name: str = "default"
        x: Optional[int] = None

    c = MockConfig()
    assert c.as_dict() == dict(name="default", x=None)
    assert c.as_dict(exclude_none=True) == dict(name="default")


def test_nested_configs():
    @dataclass
    class Bar:
        x: int
        y: int
        _z: int = 0

    @dataclass
    class Foo(Config):
        bar: Bar
        z: str

    foo = Foo(bar=Bar(x=1, y=2), z="z")
    data = foo.as_dict()
    assert isinstance(data["bar"], dict)

    foo1 = Foo.from_dict(data)
    assert foo1 == foo
    assert isinstance(foo1.bar, Bar)

    foo2 = Foo.from_dict(data, overrides=["bar.x=0"])
    assert foo2.bar.x == 0
    foo3 = foo2.merge(["bar.x=-1"])
    assert foo3.bar.x == -1

    assert foo.as_dict(recurse=False) == {"z": "z", "bar": foo.bar}

    assert foo.as_config_dict() == {
        Config.CLASS_NAME_FIELD: "test.config_test.Foo",
        "z": "z",
        "bar": {
            Config.CLASS_NAME_FIELD: "test.config_test.Bar",
            "x": 1,
            "y": 2,
        },
    }


def test_json_safe_dump():
    @dataclass
    class Foo(Config):
        x_list: List[int]
        x_tuple: Tuple[int, ...]
        x_set: Set[str]

    foo = Foo(x_list=[0, 1], x_tuple=(0, 1), x_set={"a"})
    assert foo.as_config_dict() == {
        Config.CLASS_NAME_FIELD: "test.config_test.Foo",
        "x_list": [0, 1],
        "x_tuple": [0, 1],
        "x_set": ["a"],
    }


def test_non_strict_merge():
    @dataclass
    class Bar(Config):
        x: int
        y: int

    @dataclass
    class Foo(Config):
        bar: Bar
        z: str

    foo = Foo(bar=Bar(x=1, y=2), z="a").merge(["--z=b", "--bar.x=0", "--baz.booz=0"], strict=False)
    assert foo.z == "b"
    assert foo.bar.x == 0


def test_merge_with_prefix():
    @dataclass
    class Bar(Config):
        x: int
        y: int

    @dataclass
    class Foo(Config):
        bar: Bar
        z: str

    foo = Foo(bar=Bar(x=1, y=2), z="a").merge(["--foo.z=b", "--foo.bar.x=0"], prefix="foo")
    assert foo.z == "b"
    assert foo.bar.x == 0

"""Native CUDA top16 routing indices, including boundaries and special values."""

import pytest
import torch

top16_native_indices = pytest.importorskip("olmo_core.ops.moe_top16").top16_native_indices


@pytest.mark.gpu
def test_top16_native_contract():
    if not torch.cuda.is_available():
        pytest.skip("CUDA required")
    if not torch.__version__.startswith(("2.11.", "2.13.")):
        with pytest.raises(ValueError, match="Torch 2.11"):
            top16_native_indices(torch.zeros(1, 512, device="cuda"))
        return
    torch.manual_seed(182)
    native = torch.compile(lambda x: x.topk(16, dim=-1).indices, fullgraph=True)
    candidate = torch.compile(top16_native_indices, fullgraph=True)
    for rows in (1, 17, 514, 32768):
        for case in ("random", "tied", "zeros", "signed_zero", "negative", "nonfinite"):
            x = torch.rand(rows, 512, device="cuda")
            if case == "tied":
                x = (x * 8).floor()
            elif case == "zeros":
                x.zero_()
                x[:, :200] = float("-inf")
            elif case == "signed_zero":
                x.zero_()
                x[:, :300] = -0.0
            elif case == "negative":
                x = x * 8 - 4
            elif case == "nonfinite":
                x[:, :10] = float("nan")
                x[:, 10:20] = float("inf")
                x[:, 20:200] = float("-inf")
            expected, actual = native(x), candidate(x)
            torch.testing.assert_close(expected, actual, rtol=0, atol=0, msg=f"{rows}/{case}")
